def c(code,title,n,cond=0,rec=0):
    strengths=["REQUIRED"]*(n-cond-rec)+["CONDITIONAL"]*cond+["RECOMMENDED"]*rec
    titles={
    "CP1":["Актуальность темы раскрыта","Цель сформулирована","Задачи сформулированы","Цель соответствует теме","Задачи ведут к цели","Границы рассмотрения обозначены","Структура работы объяснена"],
    "CP2":["Ключевые понятия раскрыты","Использованы релевантные источники","Подходы сопоставлены","Теория связана с темой","Есть критический анализ","Источники используются содержательно","Современные источники представлены"],
    "CP3":["Представлен анализ материала","Методы анализа понятны","Практическая часть соответствует теме","Есть собственная аналитика","Исходные данные обозначены","Результаты анализа приведены","Практическая часть применима","Артефакт описан"],
    "CP4":["Выводы опираются на анализ","Выводы отвечают цели","Задачи отражены в результатах","Нет неподтверждённых обобщений","Ограничения обозначены","Практические предложения обоснованы"],
    "CP5":["Структура последовательна","Разделы связаны","Есть заключение","Есть список источников","Ссылки согласованы со списком","Таблицы и рисунки объяснены","Приложения связаны с текстом"]}[code]
    return {"number":code,"title":title,"order_index":int(code[-1]),"description":title,"rules":[r(code,i+1,t,strengths[i],"artifact_present" if t=="Артефакт описан" else "always") for i,t in enumerate(titles)]}
